<?php
namespace EyeDonation\SiteMigrations;
defined('ABSPATH') || exit;
function fail($message){throw new \RuntimeException($message);}
function fingerprint($value){return hash('sha256',wp_json_encode($value,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE));}
function payload(){return json_decode(file_get_contents(DIR.'/payloads/approved.json'),true,512,JSON_THROW_ON_ERROR);}
function page($path){if(!$path)fail('An approved full page path is required.');$p=get_page_by_path(trim($path,'/'),OBJECT,'page');if(!$p)fail('Missing page mapping: '.$path);return $p;}
function resolve_assets(){
 $manifest=json_decode(file_get_contents(DIR.'/payloads/assets.json'),true);$config=payload();$result=[];
 foreach($manifest as $key=>$asset){$path=$config['asset_mappings'][$key]??$asset['path'];if(!is_string($path)||str_contains($path,'..')||str_starts_with($path,'/'))fail('Invalid upload-relative path: '.$key);
 $ids=get_posts(['post_type'=>'attachment','post_status'=>'inherit','numberposts'=>-1,'fields'=>'ids','meta_key'=>'_wp_attached_file','meta_value'=>$path]);
 // Scaled originals are represented by their attachment metadata, never matched by basename.
 if(!$ids){global $wpdb;$candidates=$wpdb->get_col($wpdb->prepare("SELECT post_id FROM $wpdb->postmeta WHERE meta_key='_wp_attachment_metadata' AND meta_value LIKE %s",'%'.$wpdb->esc_like(basename($path)).'%'));foreach($candidates as $id){$meta=wp_get_attachment_metadata($id);$file=get_post_meta($id,'_wp_attached_file',true);if(!empty($meta['original_image'])&&dirname($file).'/'.$meta['original_image']===$path)$ids[]=(int)$id;}}
 if(count($ids)!==1){$result[$key]=['path'=>$path,'status'=>count($ids)?'ambiguous':'missing'];continue;}
 $id=(int)$ids[0];$file=wp_get_original_image_path($id);$hash=$file&&is_file($file)?hash_file('sha256',$file):'';$status=wp_attachment_is_image($id)&&$hash?'resolved':'missing file or invalid image';if($status==='resolved'&&$hash!==$asset['sha256']&&!in_array($key,$config['approved_asset_differences'],true))$status='checksum difference requires approval';
 $result[$key]=['path'=>$path,'status'=>$status,'id'=>$id,'url'=>wp_get_attachment_image_url($id,'full'),'sha256'=>$hash,'alt'=>get_post_meta($id,'_wp_attachment_image_alt',true)?:($asset['alt']??'')];
 }return $result;
}
function required_assets(){ $assets=resolve_assets();foreach($assets as $key=>$a)if($a['status']!=='resolved')fail('Media '.$key.': '.$a['status']);return $assets; }
function navigation_markup($items){$blocks=[];foreach($items as $item){if(empty($item['label']))fail('Navigation label missing.');$attrs=['label'=>sanitize_text_field($item['label'])];if(!empty($item['page'])){$p=page($item['page']);$attrs+=['type'=>'page','kind'=>'post-type','id'=>$p->ID,'url'=>get_permalink($p)];}elseif(!empty($item['placeholder'])){$attrs+=['kind'=>'custom','url'=>placeholder_url($item['placeholder'])];}elseif(!empty($item['url'])&&filter_var($item['url'],FILTER_VALIDATE_URL)){$attrs+=['kind'=>'custom','url'=>esc_url_raw($item['url'])];}else fail('Every navigation item requires an approved page path or absolute URL.');$children=!empty($item['children'])?parse_blocks(navigation_markup($item['children'])):[];$blocks[]=['blockName'=>$children?'core/navigation-submenu':'core/navigation-link','attrs'=>$attrs,'innerBlocks'=>$children,'innerHTML'=>'','innerContent'=>$children?array_fill(0,count($children),null):[]];}return serialize_blocks($blocks);}
function managed($key,$type){$ids=get_posts(['post_type'=>$type,'post_status'=>'any','numberposts'=>-1,'fields'=>'ids','meta_key'=>'_edm_key','meta_value'=>$key]);if(count($ids)>1)fail('Ambiguous managed identity: '.$key);return $ids?(int)$ids[0]:0;}
function post_operation($key,$type,$slug,$content,$extra=[]){$id=managed($key,$type);$adopt=false;if(!$id){$mapping=payload()['adoptions'][$key]??null;if($mapping){$id=absint($mapping['destination_id']??0);$p=get_post($id);if(!$p||$p->post_type!==$type||$p->post_name!==$slug||get_post_meta($id,'_edm_key',true))fail('Invalid explicit adoption mapping: '.$key);if(hash('sha256',$p->post_content)!==($mapping['expected_content_sha256']??''))fail('Adoption baseline changed: '.$key);$adopt=true;}else{$existing=get_posts(['post_type'=>$type,'post_status'=>'any','name'=>$slug,'numberposts'=>2]);if($existing)fail('Unowned existing record requires explicit adoption mapping: '.$key);}}
 $before=$id?get_post_field('post_content',$id):null;if($id&&!$adopt&&get_post_meta($id,'_edm_fingerprint',true)!==fingerprint($before))fail('Editor change conflicts with managed content: '.$key);return ['key'=>$key,'kind'=>'post','type'=>$type,'slug'=>$slug,'id'=>$id,'before'=>$before,'after'=>$content,'extra'=>$extra,'adopt'=>$adopt,'action'=>$adopt?'adopt':($id?($before===$content?'already-satisfied':'update'):'create')];}
function bind_block(&$blocks,$marker,$id,&$count){foreach($blocks as &$b){if(($b['blockName']??'')==='core/navigation'&&in_array($marker,explode(' ',$b['attrs']['className']??''),true)){$b['attrs']['ref']=$id;$count++;}if(!empty($b['innerBlocks']))bind_block($b['innerBlocks'],$marker,$id,$count);}}
function homepage_content(){ $config=payload();$assets=required_assets();foreach(['donor','recipients','research','transplant','about','utility','video','donation'] as $key)if(empty($config['links'][$key]))fail('Missing approved homepage destination: '.$key);
 $content='';foreach(['hero','resources','history','eye-can-see-again','support','news'] as $section)$content.=file_get_contents(DIR.'/payloads/'.$section.'.html');
 if(str_contains($content,'Development placeholder'))fail('Support photograph and final Support payload are required before homepage migration.');
 foreach($assets as $key=>$asset){$content=str_replace('{{asset:'.$key.'}}',esc_url($asset['url']),$content);$content=str_replace('{{alt:'.$key.'}}',esc_attr($asset['alt']),$content);}
 foreach($config['links'] as $key=>$destination){$url=is_array($destination)&&isset($destination['placeholder'])?placeholder_url($destination['placeholder']):(is_array($destination)&&isset($destination['page'])?get_permalink(page($destination['page'])):$destination);if(!is_string($url)||!filter_var($url,FILTER_VALIDATE_URL))fail('Invalid destination: '.$key);$content=str_replace('{{link:'.$key.'}}',esc_url($url),$content);}
 if(str_contains($content,'{{'))fail('Unresolved or development-only homepage references.');
 $blocks=parse_blocks($content);remap_images($blocks,$assets);return serialize_blocks($blocks);
}
function remap_images(&$blocks,$assets){foreach($blocks as &$b){foreach($assets as $a){$match=($b['blockName']??'')==='core/image'&&str_contains($b['innerHTML'],$a['url']);$cover=($b['blockName']??'')==='core/cover'&&($b['attrs']['url']??'')===$a['url'];if($match||$cover){$b['attrs']['id']=$a['id'];$class='wp-image-'.$a['id'];$patch=function($html)use($class,$cover){return $cover?str_replace('class="wp-block-cover__image-background"','class="wp-block-cover__image-background '.$class.'"',$html):str_replace('<img ','<img class="'.$class.'" ',$html);};$b['innerHTML']=$patch($b['innerHTML']);foreach($b['innerContent'] as &$piece)if(is_string($piece))$piece=$patch($piece);unset($piece);}}if($b['innerBlocks'])remap_images($b['innerBlocks'],$assets);}}
function plan($migration){$c=payload();if(empty($c['approved']))fail('Owner-approved payload is pending. See payloads/approved.json.');$ops=[];
 switch($migration){case '001_create_approved_navigation':foreach(['primary','footer'] as $name){$items=$c[$name.'_navigation'];if(!$items)fail('Approved '.$name.' sitemap is missing.');$ops[]=post_operation('navigation.'.$name,'wp_navigation','ed-'.$name,navigation_markup($items));}break;
 case '002_bind_shared_navigation':foreach(['header'=>'primary','footer'=>'footer'] as $part=>$menu){$id=managed('navigation.'.$menu,'wp_navigation');if(!$id)fail('Navigation dependency incomplete: '.$menu);$file=get_theme_file_path('/parts/'.$part.'.html');$owned=managed('part.'.$part,'wp_template_part');$existing=get_block_template('eyedonation//'.$part,'wp_template_part');$mapping=payload()['adoptions']['part.'.$part]??null;$content=$mapping&&$existing&&$existing->source==='custom'?$existing->content:file_get_contents($file);$blocks=parse_blocks($content);$count=0;bind_block($blocks,'ed-'.$menu.'-navigation',$id,$count);if($count!==1)fail('Expected exactly one marked Navigation block in '.$part);$key='part.'.$part;$owned=managed($key,'wp_template_part');$existing=get_block_template('eyedonation//'.$part,'wp_template_part');if($existing&&$existing->source==='custom'&&!$owned&&!$mapping)fail('Unowned saved '.$part.' override requires explicit review.');$ops[]=post_operation($key,'wp_template_part',$part,serialize_blocks($blocks),['source_sha256'=>hash_file('sha256',$file),'area'=>$part]);}break;
 case '003_apply_homepage_content':$hp=$c['homepage'];if(empty($hp['approve_replacement']))fail('Homepage replacement approval missing.');$p=page($hp['path']);$before=$p->post_content;$after=homepage_content();if(hash('sha256',$before)!==$hp['expected_content_sha256']&&$before!==$after)fail('Homepage differs from approved baseline.');$ops[]=['key'=>'page.homepage','kind'=>'page','id'=>$p->ID,'before'=>$before,'after'=>$after,'action'=>$before===$after?'already-satisfied':'update'];break;
 case '004_apply_approved_page_settings':foreach($c['page_settings'] as $key=>$value){if(!in_array($key,['show_on_front','page_on_front','page_for_posts','site_logo'],true))fail('Unregistered setting: '.$key);if(!array_key_exists('expected',$value)||!array_key_exists('value',$value))fail('Each approved setting needs expected and value.');$after=$value['value'];if(in_array($key,['page_on_front','page_for_posts'],true)&&$after)$after=page($after)->ID;if($key==='site_logo'){$assets=required_assets();if(!isset($assets[$after]))fail('Unknown logo asset mapping.');$after=$assets[$after]['id'];}$before=get_option($key);if($before!=$value['expected']&&$before!=$after)fail('Setting conflict: '.$key);$ops[]=['key'=>$key,'kind'=>'option','before'=>$before,'after'=>$after,'action'=>$before==$after?'already-satisfied':'update'];}if(!$ops)fail('Approved page settings pending.');break;
 case '005_configure_search':if(!function_exists('EyeDonation\\Search\\update_settings')||!defined('EyeDonation\\Search\\VERSION')||\EyeDonation\Search\VERSION!==VERSION)fail('EyeDonation Search 0.1.0 must be active.');$after=$c['search_settings'];if(!$after)fail('Approved search settings pending.');$after=resolve_search_settings($after);$valid=\EyeDonation\Search\validate_settings($after);if(is_wp_error($valid))fail($valid->get_error_message());$before=\EyeDonation\Search\settings();if(fingerprint($before)!==$c['expected_search_settings_sha256']&&$before!==$after)fail('Search settings conflict.');$ops[]=['key'=>'search.settings','kind'=>'search','before'=>$before,'after'=>$after,'action'=>$before===$after?'already-satisfied':'update'];break;
 case '006_verify_and_rebuild_search':if(!function_exists('EyeDonation\\Search\\request_rebuild')||!defined('EyeDonation\\Search\\VERSION')||\EyeDonation\Search\VERSION!==VERSION)fail('Search plugin unavailable.');$ops[]=['key'=>'search.rebuild','kind'=>'rebuild','before'=>null,'after'=>'destination index','action'=>'rebuild'];break;
 default:fail('Unregistered migration.');}return $ops;
}
function apply_operation($op){if($op['action']==='already-satisfied')return $op['id']??null;
 switch($op['kind']){case 'post':case 'page':if($op['id']&&get_post_field('post_content',$op['id'])!==$op['before'])fail('State changed after preview.');if($op['kind']==='page'&&!current_user_can('edit_post',$op['id']))fail('Cannot edit target homepage.');$data=['post_content'=>wp_slash($op['after'])];if($op['id'])$data['ID']=$op['id'];else $data+=['post_type'=>$op['type'],'post_name'=>$op['slug'],'post_title'=>$op['slug'],'post_status'=>'publish','meta_input'=>['_edm_key'=>$op['key'],'_edm_fingerprint'=>fingerprint($op['after'])]];if(!$op['id']&&$op['kind']==='post'&&$op['type']==='wp_template_part'){$data['meta_input']['_edm_source_sha256']=$op['extra']['source_sha256'];$data['tax_input']=['wp_theme'=>['eyedonation'],'wp_template_part_area'=>[$op['extra']['area']]];} $id=$op['id']?wp_update_post($data,true):wp_insert_post($data,true);if(is_wp_error($id)||!$id)fail('Post write failed.');if(get_post_field('post_content',$id)!==$op['after'])fail('Postcondition mismatch.');if($op['kind']==='post'){update_post_meta($id,'_edm_key',$op['key']);update_post_meta($id,'_edm_fingerprint',fingerprint($op['after']));if($op['type']==='wp_template_part'){wp_set_object_terms($id,'eyedonation','wp_theme');wp_set_object_terms($id,$op['extra']['area'],'wp_template_part_area');update_post_meta($id,'_edm_source_sha256',$op['extra']['source_sha256']);}}return $id;
 case 'option':if(get_option($op['key'])!==$op['before'])fail('Option changed after preview.');update_option($op['key'],$op['after']);if(get_option($op['key'])!=$op['after'])fail('Setting verification failed.');return true;
 case 'search':if(\EyeDonation\Search\settings()!==$op['before'])fail('Search settings changed after preview.');$result=\EyeDonation\Search\update_settings($op['after']);if(is_wp_error($result))fail($result->get_error_message());return true;
 case 'rebuild':\EyeDonation\Search\request_rebuild();return 'started';}fail('Unknown operation kind.');}

function resolve_search_settings($settings){
 foreach($settings['groups']??[] as $key=>$group){foreach($group['ancestors']??[] as $index=>$path)if(is_string($path))$settings['groups'][$key]['ancestors'][$index]=page($path)->ID;
 foreach($group['terms']??[] as $taxonomy=>$terms)foreach($terms as $index=>$slug)if(is_string($slug)){$term=get_term_by('slug',$slug,$taxonomy);if(!$term||is_wp_error($term))fail('Missing search term mapping: '.$taxonomy.'/'.$slug);$settings['groups'][$key]['terms'][$taxonomy][$index]=(int)$term->term_id;}}
 return $settings;
}

function placeholder_url($key){return add_query_arg('eyedonation-placeholder',sanitize_key($key),home_url('/'));}
